'use strict';
const currentSamples=new Map();let metricLast=0;
let liveSource=null,liveURL='',liveLast=0,liveState='connecting',liveFallbackAt=0;
function liveQuery(){const q=new URLSearchParams();if(['network','security','storage','protection','lifecycle'].includes(state.page))q.set('section',state.page);const v=state.object?.vm;if(state.page==='object'&&v){q.set('connection_id',v.connection_id);q.set('node',v.node);q.set('vmid',String(v.vmid));q.set('guest_type',v.type)}return q.toString()}
function closeLive(){if(liveSource)liveSource.close();liveSource=null;liveURL=''}
function connectLive(){if(state.mode!=='live'||!state.authenticated){closeLive();if(!state.authenticated){currentSamples.clear();metricLast=0}return}if(typeof EventSource==='undefined'){liveState='fallback';return}const url='/api/events?'+liveQuery();if(liveSource&&liveURL===url)return;closeLive();liveURL=url;liveState='connecting';const source=new EventSource(url,{withCredentials:true});liveSource=source;source.addEventListener('ready',()=>{if(liveSource!==source)return;liveState='connecting';updateLiveBadge()});source.addEventListener('metrics',event=>{if(liveSource!==source)return;try{applyCurrentMetrics(JSON.parse(event.data))}catch(e){liveState='error';updateLiveBadge()}});source.addEventListener('snapshot',event=>{if(liveSource!==source)return;try{applyLiveSnapshot(JSON.parse(event.data))}catch(e){liveState='error';updateLiveBadge()}});source.addEventListener('live_error',()=>{liveState='error';updateLiveBadge()});source.addEventListener('auth_expired',()=>{closeLive();state.authenticated=false;state.csrf='';closeModal(true);authScreen(true)});source.onerror=()=>{if(liveSource!==source)return;liveState='reconnecting';updateLiveBadge()}}
function liveBadge(){const age=metricLast?Math.floor((Date.now()-metricLast)/1000):null;const metricText=age===null?'Messwerte verbinden …':age>4?'Messwerte seit '+age+' s veraltet':'Messwerte · '+age+' s alt';return `<span class="live-badge ${state.mode==='demo'?'demo':liveState==='connected'&&age!==null&&age<=4?'connected':'pending'}" data-live-badge><i></i>${state.mode==='demo'?'Beispieldaten':liveState==='connected'?metricText:liveState==='reconnecting'?'Verbindung wird erneuert':liveState==='error'?'Live-Abruf gestört':liveState==='fallback'?'Automatischer Abruf':'Live verbindet …'}</span>`}
function updateLiveBadge(){$$('[data-live-badge]').forEach(e=>{const host=document.createElement('div');host.innerHTML=liveBadge();e.replaceWith(host.firstElementChild)})}
function applyLiveSnapshot(snapshot){if(!state.authenticated||state.mode!=='live')return;liveLast=Date.now();liveState='connected';if(snapshot.failed_connections?.length){const bad=new Set(snapshot.failed_connections);snapshot.resources=[...(snapshot.resources||[]),...state.resources.filter(r=>bad.has(r.connection_id)).map(r=>({...r,stale:true,status:'unknown'}))]}Object.assign(state,{connections:snapshot.connections||state.connections,resources:snapshot.resources||state.resources,jobs:snapshot.jobs||state.jobs,operations:snapshot.operations||state.operations,updated:(snapshot.at||Date.now()/1000)*1000,error:(snapshot.errors||[]).join(' ')});if(snapshot.blueprints)state.blueprints=snapshot.blueprints;if(snapshot.catalog)state.catalog=snapshot.catalog;if(snapshot.audit)state.audit=snapshot.audit;if(snapshot.section&&snapshot.modules){snapshot.modules.sort((a,b)=>String(a.connection?.id).localeCompare(String(b.connection?.id)));state.modules[snapshot.section]=snapshot.modules;state.modules[snapshot.section].at=Date.now()}
const object=state.object;if(object?.vm){const current=state.resources.find(v=>v.connection_id===object.vm.connection_id&&v.vmid===object.vm.vmid);if(current)object.vm={...current};if(snapshot.guest_status?.ok){const status=snapshot.guest_status.data||{};Object.assign(object.vm,{status:status.status||object.vm.status,cpu:status.cpu??object.vm.cpu,mem:status.mem??object.vm.mem,maxmem:status.maxmem??object.vm.maxmem,uptime:status.uptime??object.vm.uptime})}}
if(snapshot.guest_detail&&state.object?.vm?.connection_id===snapshot.guest_connection_id&&state.object.vm.vmid===snapshot.guest_detail.vm?.vmid){const cid=state.object.vm.connection_id;Object.assign(state.object,snapshot.guest_detail);state.object.vm.connection_id=cid}overlayCurrentMetrics();renderLive();if(modalJob&&!modalBusy)jobModal(modalJob,true);if(modalOperation&&!modalBusy)operationLog(modalOperation)}
function morphLiveNode(oldNode,newNode){if(oldNode.nodeType!==newNode.nodeType||oldNode.nodeName!==newNode.nodeName){oldNode.replaceWith(newNode.cloneNode(true));return}if(oldNode.nodeType===3){if(oldNode.nodeValue!==newNode.nodeValue)oldNode.nodeValue=newNode.nodeValue;return}if(oldNode.nodeType!==1)return;const active=document.activeElement;if(oldNode.tagName==='FORM'&&(oldNode.contains(active)||oldNode.dataset.livePreserve!==undefined))return;if(oldNode.matches('[data-live-preserve]')||oldNode.id==='console-screen')return;
const isInput=['INPUT','SELECT','TEXTAREA'].includes(oldNode.tagName);for(const a of Array.from(oldNode.attributes)){if(!newNode.hasAttribute(a.name)&&!(isInput&&['value','checked','selected'].includes(a.name))&&!(a.name==='open'&&oldNode.tagName==='DETAILS'))oldNode.removeAttribute(a.name)}for(const a of Array.from(newNode.attributes)){if(isInput&&['value','checked','selected'].includes(a.name))continue;if(oldNode.getAttribute(a.name)!==a.value)oldNode.setAttribute(a.name,a.value)}
if(isInput&&oldNode.tagName!=='SELECT')return;if(oldNode.tagName==='SELECT'&&oldNode===active)return;let index=0;while(index<newNode.childNodes.length||index<oldNode.childNodes.length){let old=oldNode.childNodes[index];const fresh=newNode.childNodes[index];if(!fresh){old.remove();continue}if(fresh.nodeType===1&&fresh.id){const keyed=Array.from(oldNode.children).find(el=>el.id===fresh.id);if(keyed&&keyed!==old){oldNode.insertBefore(keyed,old||null);old=keyed}}if(!old){oldNode.append(fresh.cloneNode(true));index++;continue}if(old.nodeType===1&&old.id&&old.id!==fresh.id&&Array.from(newNode.children).some(el=>el.id===old.id)){oldNode.insertBefore(fresh.cloneNode(true),old);index++;continue}morphLiveNode(old,fresh);index++}if(oldNode.tagName==='SELECT')oldNode.value=newNode.value}
function renderLive(){if(!state.authenticated)return;if(typeof DOMParser==='undefined'){render();return}const root=$('#app'),next=new DOMParser().parseFromString('<div id="app">'+shell()+'</div>','text/html').querySelector('#app');for(const form of root.querySelectorAll('form'))form.dataset.livePreserve='';morphLiveNode(root,next);bind();updateLiveBadge();connectLive()}
async function liveFallback(){if(state.authenticated&&state.mode==='live')updateLiveBadge();if(state.mode!=='live'||!state.authenticated||document.hidden||state.busy)return;connectLive();if(liveSource&&liveState==='connected'&&Date.now()-liveLast<25000)return;const selected=Number(preferences().refresh_seconds);if(!selected)return;const seconds=Math.max(5,selected);if(Date.now()-liveFallbackAt<seconds*1000)return;liveFallbackAt=Date.now();try{await refresh(false);if(['network','security','storage','protection','lifecycle'].includes(state.page))await loadModule(state.page,true);renderLive()}catch(e){liveState='error';updateLiveBadge()}}
if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.hidden)closeLive();else if(state.authenticated)connectLive()});

function sampleKey(v){return [v.connection_id,v.type,v.node,v.vmid||0].join('/')}
function overlayCurrentMetrics(){for(const v of state.resources){const m=currentSamples.get(sampleKey(v));if(m&&!v.stale){Object.assign(v,m.sample);v.metrics_stale=Date.now()-m.received>=5000}}const o=state.object;if(o?.vm){const v=state.resources.find(v=>sampleKey(v)===sampleKey(o.vm));if(v)o.vm={...v}}}
function applyCurrentMetrics(frame){if(!state.authenticated||state.mode!=='live')return;let accepted=false;for(const sample of frame.samples||[]){const key=sampleKey(sample),old=currentSamples.get(key);if(!old||sample.sampled_at>old.sample.sampled_at){currentSamples.set(key,{sample,received:Date.now()});accepted=true}}if(accepted){metricLast=Date.now();liveLast=Date.now();liveState='connected';overlayCurrentMetrics();renderLive()}}
